    CAST(v.entered_at AS Nullable(DateTime64(3,'UTC'))) AS `stage_entered_at`,
    CAST(v.first_observed_at AS DateTime64(3,'UTC')) AS `stage_first_observed_at`,
    CAST({{ case_threshold('s.src_state_id','s.src_type_id') }} AS Nullable(Float64)) AS `stagnation_threshold_days`,
