    CAST(not v.has_observation_gap and not s.src_is_deleted AS Nullable(Bool)) AS `is_history_complete`,
    CAST(multiIf(pipeline_amount is not null and signature_probability is not null and weighted_pipeline_amount is null,'blocked',s.src_is_deleted or st.stage_key is null,'partial','ready') AS String) AS `calculation_status`,
    CAST(multiIf(pipeline_amount is not null and signature_probability is not null and weighted_pipeline_amount is null,'insufficient_decimal_scale',s.src_is_deleted,'incomplete_history',st.stage_key is null,'missing_stage_rule',NULL) AS Nullable(String)) AS `status_reason`
from s left join creation cr on s.src_tenant_id=cr.src_tenant_id and s.src_id=cr.src_id left join {{ ref('dim_company') }} co on co.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and s.src_tenant_id=co.tenant_id and s.src_company_id=co.company_id and s.boundary>=co.valid_from_at and (co.valid_to_at is null or s.boundary<co.valid_to_at) left join {{ ref('dim_employee') }} em on em.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and s.src_tenant_id=em.tenant_id and s.src_main_manager_id=em.employee_id and s.boundary>=em.valid_from_at and (em.valid_to_at is null or s.boundary<em.valid_to_at) left join {{ ref('dim_stage') }} st on st.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and s.src_tenant_id=st.tenant_id and s.src_state_id=st.stage_id and s.boundary>=st.valid_from_at and (st.valid_to_at is null or s.boundary<st.valid_to_at) left join {{ ref('dim_sale_type') }} ty on ty.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and s.src_tenant_id=ty.tenant_id and s.src_type_id=ty.sale_type_id and s.boundary>=ty.valid_from_at and (ty.valid_to_at is null or s.boundary<ty.valid_to_at) left join {{ ref('int_team_membership_periods') }} tm on tm.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and s.src_tenant_id=tm.tenant_id and s.src_main_manager_id=tm.employee_id and s.boundary>=tm.valid_from_at and (tm.valid_to_at is null or s.boundary<tm.valid_to_at) and tm.nb_simultaneous_memberships=1 left join {{ ref('dim_channel') }} ch on ch.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and s.src_tenant_id=ch.tenant_id and cr.first.1=cr.first_at and cr.first.2=ch.channel_id and cr.first.1>=ch.valid_from_at and (ch.valid_to_at is null or cr.first.1<ch.valid_to_at) left join {{ ref('int_signature_probabilities') }} pr on pr.model_run_id={{ ch_literal(var('model_run_id','parse_only')) }} and pr.tenant_id=s.src_tenant_id and pr.stage_id=s.src_state_id and pr.sales_segment=tm.sales_segment and pr.applicability_status='applicable_recomputed_case' and s.src_type_id in (4,7) and s.boundary>=pr.business_valid_from_at and s.boundary<pr.business_valid_to_at left join visit_spans v on s.src_tenant_id=v.tenant_id and s.src_id=v.opportunity_id and s.boundary>=v.first_observed_at and (v.next_visit is null or s.boundary<v.next_visit) left join membership_context md on md.tenant_id=s.src_tenant_id and md.employee_id=s.src_main_manager_id and s.boundary>=md.valid_from_at and (md.valid_to_at is null or s.boundary<md.valid_to_at)),
